-- One row per stint. Solo artists are not members of themselves: they are
-- linked to their person through artist.person_id (see 4e).
SELECT a.artist_id, p.person_id, regexp_split_to_array(m.roles, ',\s*'), m.joined_year, m.left_year
FROM (VALUES
    ('The Beatles', 'John Lennon',      'vocals, rhythm guitar, keyboards, harmonica', 1960, 1970),
    ('The Beatles', 'Paul McCartney',   'vocals, bass guitar, piano, guitar',          1960, 1970),
    ('The Beatles', 'George Harrison',  'lead guitar, vocals, sitar',                  1960, 1970),
    ('The Beatles', 'Ringo Starr',      'drums, percussion, vocals',                   1962, 1970),
    ('The Beatles', 'Pete Best',        'drums',                                       1960, 1962),
    ('The Beatles', 'Stuart Sutcliffe', 'bass guitar',                                 1960, 1961),
    ('Pink Floyd',  'Syd Barrett',      'lead guitar, vocals',                         1965, 1968),
    ('Pink Floyd',  'Roger Waters',     'bass guitar, vocals',                         1965, 1985),
    ('Pink Floyd',  'Richard Wright',   'keyboards, vocals',                           1965, 1979),
    ('Pink Floyd',  'Richard Wright',   'keyboards, vocals',                           1987, 2008),  -- rejoined
    ('Pink Floyd',  'Nick Mason',       'drums, percussion',                           1965, NULL),
    ('Pink Floyd',  'David Gilmour',    'guitar, vocals',                              1967, NULL),
    ('Daft Punk',   'Thomas Bangalter', 'production, vocoder, keyboards, guitar',      1993, 2021),
    ('Daft Punk',   'Guy-Manuel de Homem-Christo', 'production, vocoder, keyboards, guitar', 1993, 2021)
) AS m(artist, person, roles, joined_year, left_year)
JOIN artist a ON a.name = m.artist
JOIN person p ON p.name = m.person;

