UPDATE seed_album SET release_year = 1970 WHERE code = 'JJ_TRISTE';

-- Record labels, in order of first release
SELECT s.label
FROM seed_album s
GROUP BY s.label
ORDER BY min(coalesce(s.release_date, make_date(s.release_year, 1, 1))), s.label;

SELECT s.title, a.artist_id, s.release_date, s.release_year, s.album_type, l.label_id
FROM seed_album s
JOIN artist a       ON a.name = s.artist
JOIN seed_artist sa ON sa.name = s.artist
JOIN label l        ON lower(l.name) = lower(s.label)
ORDER BY sa.ord, s.release_date NULLS FIRST, s.title;

/*******************************************************************************
   2d. Tracks
   (album code, disc, track, title, composer, duration m:ss)

   Composer codes, expanded on insert:
     The Beatles                       Pink Floyd
       LM   = Lennon, McCartney          SB  = Syd Barrett
       GH   = George Harrison            RW  = Roger Waters
       RS   = Richard Starkey            DG  = David Gilmour
       JL   = John Lennon                RWR = Richard Wright
       PMC  = Paul McCartney             NM  = Nick Mason
       LMS  = Lennon, McCartney, Starkey PF  = Waters, Wright, Mason, Gilmour
       LMHS = all four                   PFS = Barrett, Waters, Wright, Mason
       GM   = George Martin
     Daft Punk
       DP   = Thomas Bangalter, Guy-Manuel de Homem-Christo
              ("DP, X" expands to both names followed by X)
   Anything else is stored as written. NULL = spoken-word track.
********************************************************************************/
CREATE TEMP TABLE seed_track (
    album    TEXT     NOT NULL REFERENCES seed_album (code),
    disc     SMALLINT NOT NULL,
    num      SMALLINT NOT NULL,
    title    TEXT     NOT NULL,
    composer TEXT,
    duration TEXT     NOT NULL,
    genre    TEXT,              -- overrides the album genre when set
    PRIMARY KEY (album, disc, num)
) ON COMMIT DROP;

CREATE TEMP TABLE seed_composer (code TEXT PRIMARY KEY, name TEXT NOT NULL) ON COMMIT DROP;


