CREATE TEMP TABLE spotify_album (
    ord          SERIAL,
    artist       TEXT NOT NULL,
    title        TEXT NOT NULL,
    release_date DATE,
    album_type   TEXT,
    label        TEXT,
    upc          TEXT,
    cover_url    TEXT,
    genres       TEXT[] NOT NULL DEFAULT '{}'  -- first one is the primary genre
) ON COMMIT DROP;



SELECT s.title, ar.artist_id, s.release_date, s.album_type, l.label_id, s.upc, s.cover_url
FROM spotify_album s
JOIN artist ar     ON ar.name = s.artist
LEFT JOIN label l  ON lower(l.name) = lower(s.label)
ORDER BY s.ord;

CREATE TEMP TABLE spotify_track (
    artist       TEXT NOT NULL,      -- album artist
    album        TEXT NOT NULL,
    disc         SMALLINT NOT NULL,
    num          SMALLINT NOT NULL,
    title        TEXT NOT NULL,
    milliseconds INT NOT NULL,
    isrc         TEXT,
    performers   TEXT[],             -- track artists, when not just the album artist
    PRIMARY KEY (artist, album, disc, num)
) ON COMMIT DROP;



-- Tracks get the album's primary genre here; 4b then drops it again (it is
-- inherited) and the trigger has added it to album_genre on the way.
SELECT st.title, al.album_id, g.genre_id, st.milliseconds, st.milliseconds * 32, st.disc, st.num, st.isrc
FROM spotify_track st
JOIN spotify_album sa ON sa.artist = st.artist AND sa.title = st.album
JOIN artist ar        ON ar.name = sa.artist
JOIN album al         ON al.artist_id = ar.artist_id AND al.title = sa.title
LEFT JOIN genre g     ON g.name = sa.genres[1]
ORDER BY sa.ord, st.disc, st.num;

-- The other genres of each album
SELECT al.album_id, g.genre_id
FROM spotify_album sa
JOIN artist ar ON ar.name = sa.artist
JOIN album al  ON al.artist_id = ar.artist_id AND al.title = sa.title
CROSS JOIN LATERAL unnest(sa.genres) AS x(genre)
JOIN genre g   ON g.name = x.genre
ON CONFLICT DO NOTHING;

-- Performers of tracks on compilations and other artists' albums. When the
-- album artist is listed first, the others are featured guests.
SELECT t.track_id, pa.artist_id,
       CASE WHEN x.n > 1 AND st.performers[1] = st.artist THEN 'featured' ELSE 'main' END,
       x.n
FROM spotify_track st
JOIN artist ar ON ar.name = st.artist
JOIN album al  ON al.artist_id = ar.artist_id AND al.title = st.album
JOIN track t   ON t.album_id = al.album_id AND t.disc_number = st.disc AND t.track_number = st.num
CROSS JOIN LATERAL unnest(st.performers) WITH ORDINALITY AS x(name, n)
JOIN artist pa ON pa.name = x.name
WHERE st.performers IS NOT NULL;


/*******************************************************************************
   4. Derived data: album artists, album genres, songs and credits
   Built from everything above: the featured artists and the Spotify library.
********************************************************************************/

/*******************************************************************************
   4a. album_artist: the credited artist of every album. The seed has no
   collaboration credits (an album by "A & B" listing A and B instead): the
   export names one artist per album.
********************************************************************************/
SELECT al.album_id, al.artist_id, 'main', 1
FROM album al;

/*******************************************************************************
   4b. album_genre: the track trigger already added every genre used by an
   album's tracks; the most common one becomes primary. Subgenres are added
   for the featured artists. Then tracks drop their genre where it is the
   album's primary genre, so only genuine exceptions keep one (e.g. George
   Martin's score on Yellow Submarine).
********************************************************************************/
UPDATE album_genre SET is_primary = false WHERE is_primary;

UPDATE album_genre ag
SET is_primary = true
FROM (
    SELECT DISTINCT ON (album_id) album_id, genre_id
    FROM track
    WHERE genre_id IS NOT NULL
    GROUP BY album_id, genre_id
    ORDER BY album_id, count(*) DESC, genre_id
) m
WHERE ag.album_id = m.album_id AND ag.genre_id = m.genre_id;

