UPDATE track t
SET genre_id = NULL
FROM album_genre ag
WHERE ag.album_id = t.album_id AND ag.is_primary AND ag.genre_id = t.genre_id;

/*******************************************************************************
   4c. Songs: music tracks by the same artist with the same title are one
   song, ignoring version labels in brackets such as "(Live)", "(Take 2)",
   "(Demo)", "(Remastered)" or "(Single Version)", or after a dash as Spotify
   writes them ("- Remastered 2009", "- Live"). The song title comes from
   its earliest recording.
********************************************************************************/
CREATE FUNCTION pg_temp.song_title(t TEXT) RETURNS TEXT
LANGUAGE sql IMMUTABLE AS $$
    SELECT coalesce(nullif(btrim(
        regexp_replace(
            regexp_replace(
                regexp_replace(t, '\s+-\s+[^-]*\m(live|demo|takes?|version|remaster(ed)?|mono|stereo|mix|remix|edit|sequence|complete|rehearsal|strings only|instrumental|acoustic|unplugged|ao vivo|en vivo|remasterizado|bonus track|\d{4})\M.*$', '', 'i'),
                '\s*[\(\[][^\)\]]*\m(live|demo|takes?|version|remaster(ed)?|mono|stereo|mix|remix|edit|sequence|complete|rehearsal|strings only|instrumental|acoustic|unplugged|ao vivo|en vivo|remasterizado|bonus track)\M[^\)\]]*[\)\]]\s*$', '', 'i'),
            '\s*[\(\[][^\)\]]*\m(live|demo|takes?|version|remaster(ed)?|mono|stereo|mix|remix|edit|sequence|complete|rehearsal|strings only|instrumental|acoustic|unplugged|ao vivo|en vivo|remasterizado|bonus track)\M[^\)\]]*[\)\]]\s*$', '', 'i')
    ), ''), t)
$$;

CREATE TEMP TABLE song_candidate ON COMMIT DROP AS
SELECT t.track_id,
       al.artist_id,
       pg_temp.song_title(t.name)        AS title,
       lower(pg_temp.song_title(t.name)) AS title_key,
       coalesce(al.release_year, 9999)   AS sort_year
FROM track t
JOIN album al ON al.album_id = t.album_id;

SELECT title, artist_id
FROM (
    SELECT DISTINCT ON (artist_id, title_key) title, artist_id, track_id
    FROM song_candidate
    ORDER BY artist_id, title_key, sort_year, track_id
) first_recording
ORDER BY track_id;

UPDATE track t
SET song_id = s.song_id
FROM song_candidate c
JOIN song s ON s.artist_id = c.artist_id AND lower(s.title) = c.title_key
WHERE t.track_id = c.track_id;

-- Year of the earliest recording in the catalog
UPDATE song s
SET first_release_year = f.release_year
FROM (
    SELECT t.song_id, min(al.release_year) AS release_year
    FROM track t
    JOIN album al ON al.album_id = t.album_id
    WHERE t.song_id IS NOT NULL
    GROUP BY t.song_id
) f
WHERE f.song_id = s.song_id AND f.release_year IS NOT NULL;

-- Lyrics language where it is certain: every José José song is in Spanish
UPDATE song s
SET language = 'es'
FROM artist ar
WHERE ar.artist_id = s.artist_id AND ar.name = 'José José';

/*******************************************************************************
   4d. Credits: songwriters of the featured artists' songs, split from the
   composer text of the song's earliest recording. "arr. X" makes X an
   arranger; "Traditional" marks the song as traditional. Writers are matched
   to existing people by name or birth name (e.g. "Richard Starkey" -> Ringo
   Starr, kept in credited_as); the rest are created. Other artists have no
   songwriter data: neither the Spotify export nor Deezer lists composers.

   From here on track.composer is generated from these credits (see the
   track_set_composer trigger), and reads the same as the original text.
********************************************************************************/
CREATE TEMP TABLE writer_token ON COMMIT DROP AS
WITH first_recording AS (
    SELECT DISTINCT ON (s.song_id) s.song_id, t.composer, t.track_id
    FROM song s
    JOIN artist ar ON ar.artist_id = s.artist_id
    JOIN track t   ON t.song_id = s.song_id
    JOIN album al  ON al.album_id = t.album_id
    WHERE ar.name IN ('The Beatles', 'Pink Floyd', 'José José', 'Daft Punk')
      AND t.composer IS NOT NULL
    ORDER BY s.song_id, coalesce(al.release_year, 9999), t.track_id
)
SELECT f.song_id,
       f.track_id,
       x.n::SMALLINT AS position,
       CASE WHEN btrim(x.token) ILIKE 'arr. %' THEN 'arranger' ELSE 'writer' END AS role,
       btrim(regexp_replace(btrim(x.token), '^arr\.\s+', '', 'i'))               AS name
FROM first_recording f
CROSS JOIN LATERAL regexp_split_to_table(f.composer, ',') WITH ORDINALITY AS x(token, n)
WHERE btrim(x.token) <> '';

SELECT w.name
FROM (SELECT name, min(track_id * 100 + position) AS first_seen
      FROM writer_token WHERE name <> 'Traditional' GROUP BY name) w
WHERE NOT EXISTS (SELECT 1 FROM person p WHERE lower(p.name) = lower(w.name) OR lower(p.birth_name) = lower(w.name))
ORDER BY w.first_seen;

SELECT DISTINCT ON (w.song_id, p.person_id, w.role)
       w.song_id, p.person_id, w.role, w.position,
       CASE WHEN w.name <> p.name THEN w.name END
FROM writer_token w
JOIN LATERAL (
    SELECT person_id, name FROM person p
    WHERE lower(p.name) = lower(w.name) OR lower(p.birth_name) = lower(w.name)
    ORDER BY (lower(p.name) = lower(w.name)) DESC, person_id
    LIMIT 1
) p ON true
WHERE w.name <> 'Traditional'
ORDER BY w.song_id, p.person_id, w.role, w.position;

UPDATE song s
SET is_traditional = true
WHERE EXISTS (SELECT 1 FROM writer_token w WHERE w.song_id = s.song_id AND w.name = 'Traditional');

/*******************************************************************************
   4e. Solo artists that are also a person in the catalog (same name, one
   match only) are linked through artist.person_id: José José.
********************************************************************************/
UPDATE artist a
SET person_id = p.person_id
FROM person p
WHERE a.artist_type = 'solo'
  AND p.name = a.name
  AND (SELECT count(*) FROM person p2 WHERE p2.name = a.name) = 1;


/*******************************************************************************
   5. Library: oscargm's 20 playlists, Liked Songs, saved albums and followed
   artists, from the Spotify export. Entries are looked up by album artist,
   album title, disc and track number; one that doesn't match stops the load.
   The export has no favorites, so every playlist stays private.
********************************************************************************/
-- A Spotify track, by album artist, album title, disc and track number
CREATE TEMP TABLE spotify_entry (
    kind     TEXT NOT NULL,       -- playlist | liked
    playlist TEXT,
    ord      INT NOT NULL,        -- order in the export
    artist   TEXT NOT NULL,
    album    TEXT NOT NULL,
    disc     SMALLINT NOT NULL,
    num      SMALLINT NOT NULL,
    added_at DATE
) ON COMMIT DROP;





ALTER TABLE spotify_entry ADD COLUMN track_id INT;

UPDATE spotify_entry e
SET track_id = t.track_id
FROM artist ar
JOIN album al ON al.artist_id = ar.artist_id
JOIN track t  ON t.album_id = al.album_id
WHERE ar.name = e.artist AND al.title = e.album
  AND t.disc_number = e.disc AND t.track_number = e.num;

DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM spotify_entry WHERE track_id IS NULL) THEN
        RAISE EXCEPTION 'seed: % Spotify entries have no track', (SELECT count(*) FROM spotify_entry WHERE track_id IS NULL);
    END IF;
END;
$$;

