SELECT p.playlist_id, e.track_id, coalesce(e.added_at + time '12:00', now())
FROM spotify_entry e
JOIN playlist p ON p.name = e.playlist
WHERE e.kind = 'playlist'
ORDER BY p.playlist_id, e.ord;

-- Liked songs. The export has no dates: saved_at keeps the export order,
-- first one newest. Two Spotify releases of one recording are one like.
SELECT u.user_id, e.track_id, now() - make_interval(secs => min(e.ord))
FROM spotify_entry e
JOIN app_user u ON u.username = 'oscargm'
WHERE e.kind = 'liked'
GROUP BY u.user_id, e.track_id
ORDER BY min(e.ord);

